import { type Citation, parse, resolve } from "../citation.ts";
import {
  type GraphChange,
  type GraphEdge,
  type GraphNode,
  isNodeId,
  KnowledgeGraph,
  type NodeId,
} from "../graph.ts";
import { changesIn, readTools, writeTools } from "../graph-tools.ts";
import type {
  Chip,
  Citations,
  Msg as GraphMsg,
  Sidebar,
  Viewport,
} from "../graph-view.ts";
import { IDENTITY_VIEWPORT, panZoom } from "../graph-view.ts";
import { interactionAt } from "../interactions.ts";
import { layout, type Position } from "../layout.ts";
import { GRAPH_UPDATE_SYSTEM, graphUpdatePrompt } from "../prompt.ts";
import { selectedSample, selectSample } from "../samples/index.ts";
import { overlaps, type ThreadId } from "../selection.ts";
import { type Message, type MessageIdx, runThread, Thread } from "../thread.ts";
import { ThreadTree } from "../threads.ts";
import { PostRenderEventBus } from "../vamp.ts";
import {
  type AppEvent,
  AppView,
  type GraphUpdate,
  type Msg,
  type State,
  type Updates,
} from "../view.ts";

/** The editable fields of a node or edge: the id addresses it, so it is not
 * part of what the sidebar edits. */
function draftOf(node: GraphNode): Omit<GraphNode, "id">;
function draftOf(edge: GraphEdge): Omit<GraphEdge, "id">;
function draftOf<T extends { id: string }>(item: T): Omit<T, "id"> {
  const { id: _id, ...rest } = item;
  return rest;
}

/** What an update thread did, read off its own transcript: a call that never
 * finished parsing or came back an error changed nothing, so it reports
 * nothing. */
function changesOf(
  messages: ReadonlyArray<Message>,
): ReadonlyArray<GraphChange> {
  return messages.flatMap((m) =>
    m.type === "tool_use" && m.call.input && m.call.result?.status === "ok"
      ? [...changesIn(m.call.result.text)]
      : [],
  );
}

function connect(): WebSocket {
  const proto = window.location.protocol === "https:" ? "wss:" : "ws:";
  return new WebSocket(`${proto}//${window.location.host}/api/socket`);
}

/** Prototype 1: the task transcript, with learning threads hanging off the
 * passages the user picks out of it. */
export function mount(container: HTMLElement): void {
  // One socket for the whole app: every Thread adds its own
  // listener and drops frames whose requestId it does not own, so streams
  // interleave over the single connection.
  const socket = connect();
  // Scoped to the user, not to a thread: it outlives every thread in the tree
  // and is discarded only by a page load.
  const graph = new KnowledgeGraph();
  const tree = new ThreadTree(
    socket,
    new Thread(socket, { initialTurns: selectedSample()?.turns }),
    () => {
      refresh();
      view.sync(state);
    },
  );
  // The thread on the left. Moved only by the arrows.
  let focus = tree.root;
  let sidebar: Sidebar = { type: "closed" };
  // Pan and zoom live beside the sidebar rather than in the view: the view
  // holds no state of its own, and a rebuild of the graph must not recentre it.
  let viewport: Viewport = IDENTITY_VIEWPORT;
  // Graph updates run one at a time: two in flight would each be handed the
  // pre-update graph and mint rival nodes for the same concept. Appending to
  // this chain is the whole serialization.
  let updates: Promise<void> = Promise.resolve();
  // What each interaction's update is doing, keyed by its address. Derived from
  // the update thread's own tool calls, so it cannot disagree with what the
  // model actually did.
  const graphUpdates = new Map<string, GraphUpdate>();
  const address = (thread: ThreadId, index: MessageIdx) => `${thread}:${index}`;
  function updatesFor(thread: ThreadId): Updates {
    const out = new Map<number, GraphUpdate>();
    for (const [key, update] of graphUpdates) {
      const [id, index] = key.split(":");
      if (id === thread) out.set(Number(index), update);
    }
    return out;
  }
  // The layout is a few hundred iterations, and refresh() runs on every
  // keystroke, so it is recomputed only when the shape of the graph changes.
  let placement = new Map<NodeId, Position>();
  let placedFor = "";
  // Purely presentational, and per thread: which messages the user has
  // expanded past the collapsed height.
  const expanded = new Map<ThreadId, Set<number>>();
  function expandedFor(id: ThreadId): Set<number> {
    let set = expanded.get(id);
    if (!set) {
      set = new Set();
      expanded.set(id, set);
    }
    return set;
  }

  const state: State = {
    sample: selectedSample()?.id ?? "",
    messages: [],
    inFlight: false,
    draft: "",
    split: false,
    depth: 0,
    canDescend: false,
    thread: focus,
    marks: [],
    activeMark: null,
    anchor: null,
    tab: "threads",
    graph: {
      nodes: [],
      edges: [],
      viewport,
      sidebar,
      citations: { description: [], notes: [] },
    },
    build: { type: "idle" },
    query: "",
    expanded: new Set(),
    updates: new Map(),
    child: null,
  };

  /** Re-projects the tree onto the view's state. Everything but the fields the
   * user is editing is derived, so this runs after every dispatch. */
  /** The graph projected onto view state: positions from `layout`, and the
   * sidebar the user is editing. */
  function refreshGraph(): void {
    const nodes = graph.nodes;
    const edges = graph.edges;
    const shape = [
      ...nodes.map((n) => n.id),
      ...edges.map((e) => `${e.id}:${e.from}->${e.to}`),
    ].join(",");
    if (shape !== placedFor) {
      placement = layout(graph);
      placedFor = shape;
    }
    const at = (id: NodeId): Position =>
      placement.get(id) ?? { x: 0.5, y: 0.5 };
    state.graph = {
      nodes: nodes.map((n) => ({ ...n, pos: at(n.id) })),
      edges: edges.map((e) => ({ ...e, from_: at(e.from), to_: at(e.to) })),
      viewport,
      sidebar,
      citations: citationsOf(),
    };
  }

  /** The citations in the *saved* prose of whatever the sidebar has open. Read
   * off the graph rather than the draft: a half-typed address is not a
   * citation, and one that does not resolve against the tree is not either. */
  function citationsOf(): Citations {
    const chips = (text: string): Chip[] =>
      parse(text).flatMap((span) => {
        if (span.type !== "citation") return [];
        const quote = resolve(tree, span.citation);
        return quote === undefined ? [] : [{ citation: span.citation, quote }];
      });
    switch (sidebar.type) {
      case "closed":
        return { description: [], notes: [] };
      case "edge": {
        const edge = graph.edge(sidebar.id);
        return { description: chips(edge?.description ?? ""), notes: [] };
      }
      case "node": {
        const node = graph.node(sidebar.id);
        return {
          description: chips(node?.description ?? ""),
          notes: chips(node?.notes ?? ""),
        };
      }
    }
  }

  function refresh(): void {
    refreshGraph();
    const node = tree.get(focus);
    state.thread = focus;
    state.depth = state.split ? tree.path(focus).length : 0;
    state.canDescend = node.activeChild !== null;
    state.messages = node.thread.messages;
    state.inFlight = node.thread.inFlight;
    state.draft = node.draft;
    state.marks = tree.marks(focus);
    state.expanded = expandedFor(focus);
    state.updates = updatesFor(focus);
    state.activeMark = node.activeChild;
    const activeChild = node.activeChild;
    if (!activeChild) {
      state.child = null;
      return;
    }
    const child = tree.get(activeChild);
    state.child = {
      messages: child.thread.messages,
      inFlight: child.thread.inFlight,
      draft: child.draft,
      expanded: expandedFor(activeChild),
      updates: updatesFor(activeChild),
    };
  }

  function sync(): void {
    refresh();
    view.sync(state);
  }

  /** One detached thread per user interaction, writing straight into the graph
   * through its tools. Queued against every other update rather than run
   * concurrently, and never awaited by the user: the learning thread answers
   * them regardless, and a failure here is invisible outside the console. */
  function queueGraphUpdate(
    thread: ThreadId,
    index: MessageIdx,
  ): Promise<boolean> {
    const interaction = interactionAt(tree, thread, index);
    const key = address(thread, index);
    graphUpdates.set(key, { type: "running" });
    // The update thread's transcript, as of its last change: the chips are read
    // off the calls it actually made, not off a side channel.
    let transcript: ReadonlyArray<Message> = [];
    const done = updates
      .then(async () => {
        // Read inside the queued step, so this update sees the previous one's
        // writes rather than the graph as it stood when it was enqueued.
        const result = await runThread(socket, {
          system: GRAPH_UPDATE_SYSTEM,
          prompt: graphUpdatePrompt(interaction, graph.render()),
          tools: writeTools(graph),
          yieldSchema: "text",
          onChange: (messages) => {
            transcript = messages;
          },
        });
        if (result.status === "error") {
          console.error(result.error);
          return false;
        }
        return true;
      })
      .catch((e: unknown) => {
        console.error(e);
        return false;
      })
      .then((ok) => {
        graphUpdates.set(key, { type: "done", changes: changesOf(transcript) });
        sync();
        return ok;
      });
    updates = done.then(() => undefined);
    return done;
  }

  /** The sample's own turns: a loaded transcript is a session that happened
   * before this page existed, so no live update ever ran over it. Every turn
   * after these came from an interaction that updated the graph itself, so
   * enumerating once at mount is what keeps the build from double-counting. */
  const sampleInteractions: MessageIdx[] = tree
    .get(tree.root)
    .thread.messages.flatMap((m, i) =>
      m.role === "user" && m.type === "text" ? [i as MessageIdx] : [],
    );

  /** Walks the loaded sample's turns through the same queue the live updates
   * use, so an interaction mid-build interleaves rather than races. */
  function runBuild(): void {
    if (state.build.type !== "idle") return;
    const total = sampleInteractions.length;
    if (total === 0) return;
    state.build = { type: "running", done: 0, total, failed: 0 };
    void (async () => {
      for (const index of sampleInteractions) {
        const ok = await queueGraphUpdate(tree.root, index);
        const build = state.build;
        if (build.type !== "running") return;
        state.build = {
          type: "running",
          done: build.done + 1,
          total: build.total,
          failed: build.failed + (ok ? 0 : 1),
        };
        sync();
      }
      const build = state.build;
      state.build = {
        type: "done",
        failed: build.type === "running" ? build.failed : 0,
      };
      sync();
    })();
  }

  function send(id: ThreadId): void {
    const node = tree.get(id);
    const text = node.draft.trim();
    if (text === "" || node.thread.inFlight) return;
    node.draft = "";
    // Nothing is streaming while the thread is idle, so the turn lands at the
    // end of `messages` - which is its citable address.
    const index = node.thread.messages.length as MessageIdx;
    node.thread.send(text).then(undefined, (e: unknown) => {
      console.error(e);
    });
    void queueGraphUpdate(id, index);
  }

  /** A citation run forwards: focus the cited thread and put the cited message
   * in front of the user. Focusing a deep thread is just setting each
   * ancestor's `activeChild`, which is the same state a mark click sets, so
   * this introduces no second notion of focus. The scroll cannot happen here -
   * the pane is not showing that thread until after the sync - so it goes out
   * on the post-render bus. */
  function reveal(state: State, citation: Citation): void {
    const path = tree.path(citation.thread);
    path.forEach((id, i) => {
      const next = path[i + 1];
      if (next) tree.get(id).activeChild = next;
    });
    focus = citation.thread;
    state.split = path.length > 1;
    state.tab = "threads";
    state.anchor = null;
    state.query = "";
    bus.emit({ type: "transcript:reveal", index: citation.index });
  }

  /** The graph tab's own reducer. It writes to the graph and to `sidebar`;
   * everything the canvas shows is re-derived in refreshGraph(). */
  function updateGraph(msg: GraphMsg): void {
    switch (msg.type) {
      case "SELECT_NODE": {
        const node = graph.node(msg.id);
        if (!node) break;
        sidebar = {
          type: "node",
          id: node.id,
          draft: draftOf(node),
          error: null,
        };
        break;
      }
      case "SELECT_EDGE": {
        const edge = graph.edge(msg.id);
        if (!edge) break;
        sidebar = {
          type: "edge",
          id: edge.id,
          draft: draftOf(edge),
          error: null,
        };
        break;
      }
      case "CLOSE":
        sidebar = { type: "closed" };
        break;
      case "NODE_FIELD":
        if (sidebar.type === "node") sidebar.draft[msg.field] = msg.value;
        break;
      case "LEVEL_CHANGED":
        if (sidebar.type === "node") sidebar.draft.level = msg.level;
        break;
      case "EDGE_FIELD":
        if (sidebar.type === "edge") sidebar.draft[msg.field] = msg.value;
        break;
      case "SAVE": {
        if (sidebar.type === "closed") break;
        const result =
          sidebar.type === "node"
            ? graph.putNode({ id: sidebar.id, ...sidebar.draft })
            : graph.putEdge({ id: sidebar.id, ...sidebar.draft });
        // A rejected save keeps the draft, so the user's typing survives.
        sidebar.error = result.status === "error" ? result.error : null;
        break;
      }
      case "DELETE": {
        if (sidebar.type === "closed") break;
        if (sidebar.type === "node") graph.deleteNode(sidebar.id);
        else graph.deleteEdge(sidebar.id);
        sidebar = { type: "closed" };
        break;
      }
      case "PAN":
      case "ZOOM":
      case "RESET_VIEW":
        viewport = panZoom(viewport, msg);
        break;
    }
  }

  function update(state: State, msg: Msg): void {
    const node = tree.get(focus);
    switch (msg.type) {
      case "DRAFT_CHANGED":
        node.draft = msg.draft;
        break;
      case "SAMPLE_CHANGED":
        selectSample(msg.id === "" ? undefined : msg.id);
        break;
      case "TAB_CHANGED":
        state.tab = msg.tab;
        break;
      case "CHANGE_CLICKED":
        state.tab = "graph";
        updateGraph(
          isNodeId(msg.id)
            ? { type: "SELECT_NODE", id: msg.id }
            : { type: "SELECT_EDGE", id: msg.id },
        );
        break;
      case "GRAPH_MSG":
        if (msg.msg.type === "CITATION_CLICKED")
          reveal(state, msg.msg.citation);
        else updateGraph(msg.msg);
        break;
      case "SUBMIT":
        send(focus);
        break;
      case "BUILD":
        runBuild();
        break;
      case "GO_DEEPER": {
        if (!state.split) {
          state.split = true;
          break;
        }
        const child = node.activeChild;
        if (!child) break;
        focus = child;
        state.anchor = null;
        state.query = "";
        break;
      }
      case "GO_BACK": {
        const parent = node.origin?.anchor.thread;
        if (parent === undefined) state.split = false;
        else focus = parent;
        state.anchor = null;
        state.query = "";
        break;
      }
      case "TOGGLE_EXPANDED": {
        const set = expandedFor(focus);
        if (!set.delete(msg.index)) set.add(msg.index);
        break;
      }
      case "SELECTION_CHANGED":
        state.anchor = msg.anchor;
        node.activeChild = null;
        break;
      case "MARK_CLICKED":
        state.anchor = null;
        node.activeChild = msg.thread;
        break;
      case "LEARNING_MSG":
        switch (msg.msg.type) {
          case "ACTION": {
            const anchor = state.anchor;
            if (!anchor || overlaps(state.marks, anchor)) break;
            const id = tree.open(anchor, msg.msg.action, {
              tools: readTools(graph),
              graph: graph.render(),
            });
            state.anchor = null;
            state.query = "";
            void queueGraphUpdate(id, 0 as MessageIdx);
            tree
              .get(id)
              .thread.start()
              .then(undefined, (e: unknown) => {
                console.error(e);
              });
            break;
          }
          case "QUERY_CHANGED":
            state.query = msg.msg.query;
            break;
        }
        break;
      case "CHILD_MSG": {
        const activeChild = node.activeChild;
        if (!activeChild) break;
        switch (msg.msg.type) {
          case "DRAFT_CHANGED":
            tree.get(activeChild).draft = msg.msg.draft;
            break;
          case "SUBMIT":
            send(activeChild);
            break;
          case "TOGGLE_EXPANDED": {
            const set = expandedFor(activeChild);
            if (!set.delete(msg.msg.index)) set.add(msg.msg.index);
            break;
          }
          case "CHANGE_CLICKED":
            update(state, msg.msg);
            break;
        }
        break;
      }
    }
    refresh();
  }

  // Scroll and flash are the one thing that cannot live in a reducer or a
  // binding: they need the DOM to already reflect the new focus.
  const bus = new PostRenderEventBus<AppEvent>();

  let dispatching = false;
  function dispatch(msg: Msg): void {
    if (dispatching) throw new Error("dispatch-in-dispatch");
    dispatching = true;
    update(state, msg);
    view.sync(state);
    bus.flush();
    dispatching = false;
  }

  // e2e specs seed a known graph through this handle rather than driving the
  // extraction thread first, so the sidebar cases stay deterministic.
  (window as unknown as { __graph?: KnowledgeGraph }).__graph = graph;

  refresh();
  const view = new AppView(container, dispatch, state, { bus });
}

import type Anthropic from "@anthropic-ai/sdk";
import {
  type Action,
  askTurn,
  contextSeed,
  LEARNING_SYSTEM,
} from "./prompt.ts";
import type { Anchor, Mark, ThreadId } from "./selection.ts";
import type { Tool, ToolName, TurnResult } from "./thread.ts";
import { type Socket, Thread } from "./thread.ts";

export type { Action };

/** `anchor.thread` is the parent, so the link upward is the highlight itself. */
export type Origin = { anchor: Anchor; action: Action };

/** What a child thread is given beyond its seed. */
export type ChildOpts = {
  tools?: Record<ToolName, Tool>;
  /** The rendered knowledge graph, injected into the seed of a top-level
   * learning thread. */
  graph?: string;
  yieldSchema?: Anthropic.Tool.InputSchema | "text";
};

export type TreeNode = {
  id: ThreadId;
  /** null only for the root task thread. */
  origin: Origin | null;
  thread: Thread;
  /** Creation order; each child's `origin.anchor` is its highlight. */
  children: ThreadId[];
  activeChild: ThreadId | null;
  draft: string;
};

/** The tree of threads. Every thread but the root was opened from a
 * passage of its parent, so a thread and the highlight over its parent are the
 * same edge seen from either end. Threads are never destroyed or reparented. */
export class ThreadTree {
  private readonly threads = new Map<ThreadId, TreeNode>();
  private nextId = 0;
  readonly root: ThreadId;
  private readonly socket: Socket;
  /** Attached to every thread the tree owns, so a stream anywhere in the
   * tree re-syncs the app. */
  private readonly onChange: () => void;

  constructor(socket: Socket, root: Thread, onChange: () => void) {
    this.socket = socket;
    this.onChange = onChange;
    this.root = this.add(null, root);
  }

  get(id: ThreadId): TreeNode {
    const node = this.threads.get(id);
    if (!node) throw new Error(`unknown thread ${id}`);
    return node;
  }

  /** Seeds a child thread from the parent's own seed plus its transcript
   * up to `anchor`, links it in, and makes it the parent's active child. The
   * caller starts it: the tree does not own the request lifecycle. */
  open(anchor: Anchor, action: Action, opts: ChildOpts = {}): ThreadId {
    const parent = this.get(anchor.thread);
    const thread = new Thread(this.socket, {
      system: LEARNING_SYSTEM,
      seed: contextSeed(
        typeof parent.thread.seed === "string" ? parent.thread.seed : undefined,
        parent.thread.messages,
        anchor,
        opts.graph,
      ),
      initialTurns: [
        {
          role: "user",
          content: askTurn(anchor, parent.thread.messages, action),
        },
      ],
      tools: opts.tools,
      yieldSchema: opts.yieldSchema,
    });
    const id = this.add({ anchor, action }, thread);
    parent.children.push(id);
    parent.activeChild = id;
    return id;
  }

  /** What a child thread settled with, once it has yielded. The parent renders
   * threads it never awaited, so the settled value has to be readable here. */
  result(id: ThreadId): TurnResult | undefined {
    return this.get(id).thread.result;
  }

  /** The highlights to draw over `id`'s transcript: one per child. */
  marks(id: ThreadId): Mark[] {
    return this.get(id).children.map((child) => {
      const origin = this.get(child).origin;
      if (!origin) throw new Error("child thread without an origin");
      return { thread: child, anchor: origin.anchor };
    });
  }

  /** root -> id, for the depth indicator. */
  path(id: ThreadId): ThreadId[] {
    const out: ThreadId[] = [];
    let at: ThreadId | undefined = id;
    while (at) {
      out.unshift(at);
      at = this.get(at).origin?.anchor.thread;
    }
    return out;
  }

  private add(origin: Origin | null, thread: Thread): ThreadId {
    const id = `t${this.nextId++}` as ThreadId;
    thread.onChange = this.onChange;
    this.threads.set(id, {
      id,
      origin,
      thread,
      children: [],
      activeChild: null,
      draft: "",
    });
    return id;
  }
}

import type { ThreadId } from "./selection.ts";
import { type Message, type MessageIdx, messageText } from "./thread.ts";
import type { ThreadTree } from "./threads.ts";

/** One user interaction, captured as it happens. The unit of evidence about
 * what this user understands. */
export type Interaction = {
  thread: ThreadId;
  /** Index into that thread's `messages`. With `thread`, this is the citable
   * address. A learning thread's ask is its own message 0, so there is no
   * special case. */
  index: MessageIdx;
  /** The thread's seed, then its blocks before the turn - which are messages
   * 0 to index-1, so their addresses are their positions. Identical across
   * interactions in the same thread up to their split point; the prompt cache
   * depends on that. */
  prefix: {
    seed: string | undefined;
    messages: ReadonlyArray<Message>;
  };
  /** The user's turn. */
  text: string;
};

/** The interaction the user just made: the turn at `index` in `thread`. */
export function interactionAt(
  tree: ThreadTree,
  thread: ThreadId,
  index: MessageIdx,
): Interaction {
  const node = tree.get(thread);
  const messages = node.thread.messages;
  const message = messages[index];
  if (!message) {
    throw new Error(`no message ${index} in thread ${thread}`);
  }
  if (message.role !== "user") {
    throw new Error(`message ${index} in thread ${thread} is not a user turn`);
  }
  return {
    thread,
    index,
    prefix: {
      // Only a learning thread's seed is prose; a graph update's seed is
      // content blocks, and those threads have no interactions in them.
      seed: typeof node.thread.seed === "string" ? node.thread.seed : undefined,
      messages: messages.slice(0, index),
    },
    text: messageText(message),
  };
}

/** One id space over nodes and edges, so `get` takes a single list. */
export type GraphId = NodeId | EdgeId;
/** Minted by the graph (`n0`, `n1`, ...). Opaque; never derived from the title. */
export type NodeId = string & { readonly __brand: "NodeId" };
/** Minted by the graph (`e0`, `e1`, ...). */
export type EdgeId = string & { readonly __brand: "EdgeId" };

/** The agent's estimate, not a measurement. A misconception can look fluent,
 * so it belongs in `notes`, not here. */
export type Level = 1 | 2 | 3 | 4;
export const LEVELS = ["unfamiliar", "emerging", "working", "fluent"] as const;

export const levelLabel = (level: Level) => `${level} ${LEVELS[level - 1]}`;

export type GraphNode = {
  id: NodeId;
  /** Unique among nodes and non-empty, up to ~5 words. A label, not the key. */
  title: string;
  /** What the domain knowledge itself is. */
  description: string;
  /** The agent's read on this user's grasp of it, including misconceptions. */
  notes: string;
  level: Level;
};

export type GraphEdge = {
  id: EdgeId;
  from: NodeId;
  to: NodeId;
  /** 1-2 words. Several edges may join the same pair. */
  title: string;
  description: string;
};

/** One applied mutation. Structured rather than prose because it is read twice:
 * by the model, off the tool result, and by the transcript chip that reports
 * what a background graph update just did. */
export type GraphChange = {
  op: "created" | "updated" | "deleted";
  kind: "node" | "edge";
  id: GraphId;
  title: string;
};
export type GraphResult =
  | { status: "ok"; change: GraphChange }
  | { status: "error"; error: string };

export const isNodeId = (id: string): id is NodeId => id.startsWith("n");
export const isEdgeId = (id: string): id is EdgeId => id.startsWith("e");

export class KnowledgeGraph {
  #nodes = new Map<NodeId, GraphNode>();
  #edges = new Map<EdgeId, GraphEdge>();
  #next = 0;

  get nodes(): ReadonlyArray<GraphNode> {
    return [...this.#nodes.values()];
  }

  get edges(): ReadonlyArray<GraphEdge> {
    return [...this.#edges.values()];
  }

  node(id: NodeId): GraphNode | undefined {
    return this.#nodes.get(id);
  }

  edge(id: EdgeId): GraphEdge | undefined {
    return this.#edges.get(id);
  }

  /** Creates with a fresh id when `id` is omitted, updates in place when it is
   * given. Rejects an unknown id, an empty title, or a title already used by
   * another node. */
  putNode(node: Omit<GraphNode, "id"> & { id?: NodeId }): GraphResult {
    const title = node.title.trim();
    if (title === "") return { status: "error", error: "node title is empty" };
    if (node.id !== undefined && !this.#nodes.has(node.id))
      return { status: "error", error: `no node with id ${node.id}` };
    for (const other of this.#nodes.values())
      if (other.title === title && other.id !== node.id)
        return {
          status: "error",
          error: `title "${title}" is already used by node ${other.id}`,
        };
    const id = node.id ?? (`n${this.#next++}` as NodeId);
    this.#nodes.set(id, {
      id,
      title,
      description: node.description,
      notes: node.notes,
      level: node.level,
    });
    return {
      status: "ok",
      change: {
        op: node.id === undefined ? "created" : "updated",
        kind: "node",
        id,
        title,
      },
    };
  }

  /** Cascades to incident edges. */
  deleteNode(id: NodeId): GraphResult {
    const node = this.#nodes.get(id);
    if (!node) return { status: "error", error: `no node with id ${id}` };
    for (const edge of [...this.#edges.values()])
      if (edge.from === id || edge.to === id) this.#edges.delete(edge.id);
    this.#nodes.delete(id);
    return {
      status: "ok",
      change: { op: "deleted", kind: "node", id, title: node.title },
    };
  }

  /** Errors if either endpoint is unknown. */
  putEdge(edge: Omit<GraphEdge, "id"> & { id?: EdgeId }): GraphResult {
    const title = edge.title.trim();
    if (title === "") return { status: "error", error: "edge title is empty" };
    if (edge.id !== undefined && !this.#edges.has(edge.id))
      return { status: "error", error: `no edge with id ${edge.id}` };
    if (!this.#nodes.has(edge.from))
      return { status: "error", error: `no node with id ${edge.from}` };
    if (!this.#nodes.has(edge.to))
      return { status: "error", error: `no node with id ${edge.to}` };
    if (edge.from === edge.to)
      return {
        status: "error",
        error: "an edge may not join a node to itself",
      };
    const id = edge.id ?? (`e${this.#next++}` as EdgeId);
    this.#edges.set(id, {
      id,
      from: edge.from,
      to: edge.to,
      title,
      description: edge.description,
    });
    return {
      status: "ok",
      change: {
        op: edge.id === undefined ? "created" : "updated",
        kind: "edge",
        id,
        title,
      },
    };
  }

  deleteEdge(id: EdgeId): GraphResult {
    const edge = this.#edges.get(id);
    if (!edge) return { status: "error", error: `no edge with id ${id}` };
    this.#edges.delete(id);
    return {
      status: "ok",
      change: { op: "deleted", kind: "edge", id, title: edge.title },
    };
  }

  /** Everything about each id: a node with its incident edges in both
   * directions, or an edge with its endpoints. Unknown ids come back marked
   * as such rather than failing the batch. */
  get(ids: ReadonlyArray<GraphId>): string {
    return ids.map((id) => this.#record(id)).join("\n\n");
  }

  #record(id: GraphId): string {
    const node = this.#nodes.get(id as NodeId);
    if (node) {
      const incident = this.edges.filter(
        (e) => e.from === node.id || e.to === node.id,
      );
      return [
        `node ${node.id} "${node.title}" level ${levelLabel(node.level)}`,
        `description: ${node.description}`,
        `notes: ${node.notes}`,
        incident.length === 0
          ? "edges: (none)"
          : [
              "edges:",
              ...incident.map(
                (e) =>
                  `  ${e.id} "${e.title}" ${this.#label(e.from)} -> ${this.#label(e.to)}`,
              ),
            ].join("\n"),
      ].join("\n");
    }
    const edge = this.#edges.get(id as EdgeId);
    if (edge)
      return [
        `edge ${edge.id} "${edge.title}" ${this.#label(edge.from)} -> ${this.#label(edge.to)}`,
        `description: ${edge.description}`,
      ].join("\n");
    return `${id}: not found`;
  }

  #label(id: NodeId): string {
    const node = this.#nodes.get(id);
    return node ? `${id} "${node.title}"` : `${id} (missing)`;
  }

  /** The overview - one line per node and edge, id and title and level -
   * injected into the seed of any thread that needs it. An empty graph renders
   * as a line saying so, not as "". */
  render(): string {
    if (this.#nodes.size === 0 && this.#edges.size === 0)
      return "The knowledge graph is empty: it has no nodes and no edges yet.";
    return [
      "nodes:",
      ...this.nodes.map(
        (n) => `  ${n.id} "${n.title}" - ${levelLabel(n.level)}`,
      ),
      "edges:",
      ...(this.#edges.size === 0
        ? ["  (none)"]
        : this.edges.map((e) => `  ${e.id} "${e.title}" ${e.from} -> ${e.to}`)),
    ].join("\n");
  }
}

import type Anthropic from "@anthropic-ai/sdk";
import type { ClientMessage, ServerFrame } from "@edulab/iso/protocol.ts";

const MODEL = "claude-opus-4-5";
const MAX_TOKENS = 16384;
// Task mode: the agent is here to get the user's work done. Learning mode is
// the secondary mode we layer on top of a transcript this produces, so this
// prompt must not pre-emptively tutor - the whole premise of the prototype is
// that a user watching a capable agent work becomes a passive observer.
const SYSTEM = [
  "You are a capable engineering assistant helping the user complete a task.",
  "Work the problem directly: make concrete decisions, write real code, and",
  "state your reasoning as you go rather than asking the user to supply it.",
  "Be concise. Do not quiz the user, do not pad explanations for a beginner,",
  "and do not check whether they are following - just do the work well.",
].join(" ");

// Unattended mode: nobody is reading the transcript as it streams, so a
// question to the user is a dead end. The only exit is the yield tool.
const AUTONOMOUS_SYSTEM = [
  "You are a capable engineering assistant running unattended: there is no",
  "user to answer questions, and nothing you say outside the yield tool will",
  "be read. Work the problem to completion, making whatever decisions you",
  "need without asking, and finish by calling the yield tool exactly once",
  "with your result. Do not stop for confirmation and do not ask questions.",
].join(" ");

const MAX_RESTARTS = 5;
const restartNudge = (attempt: number, max: number) =>
  `You stopped without yielding. Nobody read that message. Complete the task and call the yield tool when you are done. (auto-restart ${attempt}/${max})`;

const YIELD = "yield";
const DEFAULT_YIELD_SCHEMA: Anthropic.Tool.InputSchema = {
  type: "object",
  properties: {
    result: {
      type: "string",
      description: "The result to return to whoever spawned this thread.",
    },
  },
  required: ["result"],
};

export type ToolCall = {
  id: string;
  name: string;
  /** Parsed from the streamed json; undefined while still streaming or if it
   * never parsed. */
  input: Record<string, unknown> | undefined;
  /** Raw accumulated json, so a partial call is still renderable. */
  inputJson: string;
  /** Derived from the paired tool_result block in the next user turn; absent
   * while the tool is still running. */
  result: ToolResult | undefined;
};

export type YieldValue =
  | { type: "text"; text: string }
  | { type: "structured"; value: Record<string, unknown> };

export type TurnResult =
  | { type: "completed" }
  | { type: "yielded"; value: YieldValue }
  | { type: "error"; message: string };

export type ThreadOpts = {
  system?: string;
  /** Sent after the seed, and rendered: a learning thread's opening ask is
   * one of these, not part of the seed. */
  initialTurns?: Anthropic.MessageParam[];
  /** Content blocks rather than a string when the caller needs `cache_control`
   * on part of it - a graph update marks its stable prefix. */
  seed?: string | Anthropic.ContentBlockParam[];
  tools?: Record<ToolName, Tool>;
  /** Present => the yield tool is offered. `"text"` uses the default
   * `{ result: string }` schema and settles with a text value; a schema
   * settles with the whole input object. */
  yieldSchema?: Anthropic.Tool.InputSchema | "text";
};

/** The key of a tool in the record handed to a thread; also what the model
 * sends back as `tool_use.name`. */
export type ToolName = string & { readonly __brand: "ToolName" };

export type ToolResult =
  | { status: "ok"; text: string }
  | { status: "error"; error: string };
/** A tool the thread can run, client side. */
export type Tool = {
  spec: Anthropic.Tool;
  execute(input: Record<string, unknown>): Promise<ToolResult>;
};

/** Keys a set of tools by name. `Record<ToolName, Tool>` is a mapped type over
 * a branded string, so an object literal cannot be written for it directly. */
export function toolset(...tools: ReadonlyArray<Tool>): Record<ToolName, Tool> {
  return Object.fromEntries(tools.map((t) => [t.spec.name, t]));
}

/** One entry of the derived transcript: a block, not a turn. A single agent
 * turn can produce prose, a tool call, and more prose, and the transcript shows
 * it that way. */
export type Message =
  | { type: "text"; role: "user" | "assistant"; text: string }
  | { type: "tool_use"; role: "assistant"; call: ToolCall };

/** A position in a thread's `messages`. Branded because it is an identifier -
 * half of the `(thread, index)` address an interaction and a citation are
 * written as - and only ever produced by reading a real position. */
export type MessageIdx = number & { readonly __brand: "MessageIdx" };

/** Anchors index into text entries only, so everything else has no text. */
export function messageText(message: Message): string {
  return message.type === "text" ? message.text : "";
}

/** A block of the assistant turn currently streaming. */
type PendingBlock =
  | { type: "text"; text: string }
  | {
      type: "tool_use";
      id: string;
      name: string;
      inputJson: string;
      input: Record<string, unknown> | undefined;
    };

/** The subset of WebSocket the thread uses, so tests can stand in for it. */
export type Socket = {
  send(data: string): void;
  addEventListener(
    type: "message",
    listener: (e: MessageEvent<string>) => void,
  ): void;
};

export type ThreadResult<Value> =
  | { status: "ok"; result: Value }
  | { status: "error"; error: string };

export type RunThreadOpts = {
  prompt: string | Anthropic.ContentBlockParam[];
  tools?: Record<ToolName, Tool>;
  yieldSchema: Anthropic.Tool.InputSchema | "text";
  system?: string;
  /** How many times a turn that ends without a yield is nudged back to work. */
  maxRestarts?: number;
  /** Fires whenever the thread's transcript changes, so a caller can watch an
   * unattended thread work rather than only awaiting its result. */
  onChange?: (messages: ReadonlyArray<Message>) => void;
};

/** Runs a thread to completion with no user in the loop: the seed prompt goes
 * in, tools run client side, and the settled yield comes back. A turn that
 * ends without yielding is restarted rather than accepted. */
export function runThread(
  socket: Socket,
  opts: RunThreadOpts & { yieldSchema: "text" },
): Promise<ThreadResult<string>>;
export function runThread<Value extends Record<string, unknown>>(
  socket: Socket,
  opts: RunThreadOpts & { yieldSchema: Anthropic.Tool.InputSchema },
): Promise<ThreadResult<Value>>;
export async function runThread(
  socket: Socket,
  opts: RunThreadOpts,
): Promise<ThreadResult<string | Record<string, unknown>>> {
  const maxRestarts = opts.maxRestarts ?? MAX_RESTARTS;
  const thread = new Thread(socket, {
    system: opts.system ?? AUTONOMOUS_SYSTEM,
    seed: opts.prompt,
    tools: opts.tools,
    yieldSchema: opts.yieldSchema,
  });
  const onChange = opts.onChange;
  if (onChange) thread.onChange = () => onChange(thread.messages);
  let result = await thread.start();
  for (let attempt = 1; result.type === "completed"; attempt++) {
    if (attempt > maxRestarts) {
      return {
        status: "error",
        error: `thread stopped without yielding after ${maxRestarts} restarts`,
      };
    }
    result = await thread.send(restartNudge(attempt, maxRestarts));
  }
  return result.type === "yielded"
    ? {
        status: "ok",
        result:
          result.value.type === "text" ? result.value.text : result.value.value,
      }
    : { status: "error", error: result.message };
}

export class Thread {
  private readonly turns: Anthropic.MessageParam[];
  private pending:
    | {
        requestId: string;
        blocks: PendingBlock[];
        stopReason: string | null;
      }
    | undefined;
  /** Bumped whenever the log or the streaming block changes, so `messages` can
   * be recomputed lazily rather than on every delta. */
  private version = 0;
  private cache:
    | { version: number; messages: ReadonlyArray<Message> }
    | undefined;
  private settle:
    | ((content: Anthropic.ContentBlockParam[]) => void)
    | undefined;
  /** True for the whole agent turn, including while tools execute between
   * requests - the UI and the send guard care about the turn, not the request. */
  private running = false;
  /** Set when a request ends in a done/error frame, which ends the turn even
   * if tools were requested. */
  private failed = false;
  /** tool_use ids whose streamed json never parsed. The log has to carry an
   * object the API would accept, so this is the only place that knowledge
   * survives the commit. */
  private readonly unparsed = new Set<string>();
  onChange: (() => void) | undefined;

  private readonly socket: Socket;
  private readonly system: string;
  private readonly tools: Record<ToolName, Tool>;
  /** Present => the yield tool is offered and the turn can settle with data. */
  private readonly yieldSchema: Anthropic.Tool.InputSchema | "text" | undefined;
  private settled: TurnResult | undefined;
  /** Turn 0 when present: sent like any other turn, never rendered. */
  readonly seed: string | Anthropic.ContentBlockParam[] | undefined;

  constructor(socket: Socket, opts: ThreadOpts = {}) {
    this.socket = socket;
    this.system = opts.system ?? SYSTEM;
    this.tools = opts.tools ?? {};
    this.yieldSchema = opts.yieldSchema;
    this.seed = opts.seed;
    this.turns = [
      ...(opts.seed ? [{ role: "user" as const, content: opts.seed }] : []),
      ...(opts.initialTurns ?? []),
    ];
    socket.addEventListener("message", (e: MessageEvent<string>) => {
      this.handleFrame(JSON.parse(e.data) as ServerFrame);
    });
  }

  /** The derived transcript: the log flattened into blocks, plus whatever is
   * currently streaming. The log stays the wire format; nothing is ever
   * converted back out of `Message`. */
  get messages(): ReadonlyArray<Message> {
    if (this.cache?.version === this.version) return this.cache.messages;
    const messages = project(
      this.seed ? this.turns.slice(1) : this.turns,
      this.pending?.blocks,
    );
    this.cache = { version: this.version, messages };
    return messages;
  }

  get inFlight(): boolean {
    return this.running;
  }

  /** The settled yield, once the thread has produced one. */
  get result(): TurnResult | undefined {
    return this.settled;
  }

  send(text: string): Promise<TurnResult> {
    if (this.running) return Promise.resolve({ type: "completed" });
    this.turns.push({ role: "user", content: text });
    this.version++;
    return this.run();
  }

  /** Requests a reply to the turns already present - the seeded first turn of
   * a learning thread, which the user never typed. */
  start(): Promise<TurnResult> {
    if (this.running || this.turns.length === 0)
      return Promise.resolve({ type: "completed" });
    return this.run();
  }

  /** One agent turn: request, execute whatever tools the model asked for,
   * request again, until it replies without calling any. */
  private async run(): Promise<TurnResult> {
    this.running = true;
    this.failed = false;
    try {
      for (;;) {
        const content = await this.request();
        if (this.failed) return { type: "error", message: "request ended" };
        const calls = content.filter(
          (block): block is Anthropic.ToolUseBlockParam =>
            block.type === "tool_use",
        );
        if (calls.length === 0) return { type: "completed" };
        // Every tool_use must be answered by exactly one tool_result in the
        // immediately following user turn, in request order, or the next
        // request is rejected outright.
        const results = await Promise.all(
          calls.map((call) => this.execute(call)),
        );
        this.turns.push({ role: "user", content: results });
        this.version++;
        this.onChange?.();
        // Yield is not special-cased during execution: the whole batch runs and
        // every result lands in the log, and only then does the turn stop.
        const yielded = calls.find((call) => this.isYield(call.name));
        if (yielded) {
          const result: TurnResult = {
            type: "yielded",
            value: this.yieldValue(
              (yielded.input ?? {}) as Record<string, unknown>,
            ),
          };
          this.settled = result;
          return result;
        }
      }
    } finally {
      this.running = false;
      this.onChange?.();
    }
  }

  private isYield(name: string): boolean {
    return this.yieldSchema !== undefined && name === YIELD;
  }

  private yieldValue(input: Record<string, unknown>): YieldValue {
    return this.yieldSchema === "text"
      ? { type: "text", text: String(input.result ?? "") }
      : { type: "structured", value: input };
  }

  private toolSpecs(): Anthropic.Tool[] {
    const specs = Object.values(this.tools).map((tool) => tool.spec);
    if (this.yieldSchema !== undefined) {
      specs.push({
        name: YIELD,
        description:
          "Finish this thread and return your result to whoever spawned it. Call this exactly once, when you are done; do not call it before you have finished the work.",
        input_schema:
          this.yieldSchema === "text" ? DEFAULT_YIELD_SCHEMA : this.yieldSchema,
      });
    }
    return specs;
  }

  private async execute(
    call: Anthropic.ToolUseBlockParam,
  ): Promise<Anthropic.ToolResultBlockParam> {
    const result: ToolResult = this.unparsed.has(call.id)
      ? { status: "error", error: "could not parse tool input" }
      : this.isYield(call.name)
        ? // Echoing the yielded payload back at the model only spends tokens.
          { status: "ok", text: "Yield acknowledged." }
        : await runTool(this.tools[call.name as ToolName], call);
    return {
      type: "tool_result",
      tool_use_id: call.id,
      content: result.status === "ok" ? result.text : result.error,
      is_error: result.status === "error",
    };
  }

  /** Resolves with the assistant content the request committed. */
  private request(): Promise<Anthropic.ContentBlockParam[]> {
    const specs = this.toolSpecs();
    const requestId = crypto.randomUUID();
    this.pending = { requestId, blocks: [], stopReason: null };
    this.version++;
    const message: ClientMessage = {
      type: "start",
      requestId,
      params: {
        model: MODEL,
        max_tokens: MAX_TOKENS,
        system: this.system,
        stream: true,
        messages: [...this.turns],
        ...(specs.length > 0 ? { tools: specs } : {}),
      },
    };
    this.socket.send(JSON.stringify(message));
    this.onChange?.();
    return new Promise<Anthropic.ContentBlockParam[]>((resolve) => {
      this.settle = resolve;
    });
  }

  handleFrame(frame: ServerFrame): void {
    const pending = this.pending;
    if (!pending || frame.requestId !== pending.requestId) return;
    switch (frame.type) {
      case "event":
        this.handleEvent(frame.event);
        break;
      case "done":
      case "error":
        this.failed = true;
        // A turn that ends without a message_stop still commits whatever text
        // arrived, so the next turn's array stays valid.
        this.commit();
        break;
    }
    this.version++;
    this.onChange?.();
  }

  private handleEvent(event: Anthropic.RawMessageStreamEvent): void {
    const pending = this.pending;
    if (!pending) return;
    // RawMessageStreamEvent is an open union we forward verbatim from the SDK,
    // so an unrecognized event warns rather than throwing - a version bump
    // should not break a stream we can otherwise render.
    switch (event.type) {
      case "content_block_start": {
        const block = startBlock(event.content_block);
        if (block) pending.blocks[event.index] = block;
        break;
      }
      case "content_block_delta":
        appendDelta(pending.blocks[event.index], event.delta);
        break;
      case "content_block_stop": {
        const block = pending.blocks[event.index];
        // The model's json only becomes readable once it is complete; a stream
        // cut short leaves `input` undefined and the partial json in place.
        if (block?.type === "tool_use")
          block.input = parseInput(block.inputJson);
        break;
      }
      case "message_delta":
        pending.stopReason = event.delta.stop_reason;
        break;
      case "message_stop":
        this.commit();
        break;
      case "message_start":
        break;
      default:
        console.warn("unhandled stream event", event);
    }
  }

  private commit(): void {
    const pending = this.pending;
    if (!pending) return;
    this.pending = undefined;
    for (const block of pending.blocks) {
      if (block?.type === "tool_use" && block.input === undefined) {
        this.unparsed.add(block.id);
      }
    }
    const content = commitBlocks(pending.blocks);
    // MessageParam content must be non-empty, so an empty response is dropped.
    if (content.length > 0) this.turns.push({ role: "assistant", content });
    this.settle?.(content);
    this.settle = undefined;
  }
}

async function runTool(
  tool: Tool | undefined,
  call: Anthropic.ToolUseBlockParam,
): Promise<ToolResult> {
  if (!tool) return { status: "error", error: `unknown tool: ${call.name}` };
  // Validating input against input_schema is the API's job; the client only
  // checks that the streamed json parsed at all, which it did by here.
  const input = (call.input ?? {}) as Record<string, unknown>;
  try {
    return await tool.execute(input);
  } catch (error) {
    return { status: "error", error: String(error) };
  }
}

function commitBlocks(
  blocks: ReadonlyArray<PendingBlock>,
): Anthropic.ContentBlockParam[] {
  const out: Anthropic.ContentBlockParam[] = [];
  for (const block of blocks) {
    if (!block) continue;
    if (block.type === "text") {
      if (block.text.length > 0) out.push({ type: "text", text: block.text });
    } else {
      out.push({
        type: "tool_use",
        id: block.id,
        name: block.name,
        input: block.input ?? {},
      });
    }
  }
  return out;
}

/** Flattens the log into transcript entries, pairing each tool call with the
 * result that arrives in the following user turn. */
function project(
  turns: ReadonlyArray<Anthropic.MessageParam>,
  streaming: ReadonlyArray<PendingBlock> | undefined,
): ReadonlyArray<Message> {
  const results = new Map<string, ToolResult>();
  for (const turn of turns) {
    if (typeof turn.content === "string") continue;
    for (const block of turn.content) {
      if (block.type === "tool_result") {
        results.set(block.tool_use_id, toolResult(block));
      }
    }
  }

  const out: Message[] = [];
  for (const turn of turns) {
    const role = turn.role === "assistant" ? "assistant" : "user";
    if (typeof turn.content === "string") {
      out.push({ type: "text", role, text: turn.content });
      continue;
    }
    for (const block of turn.content) {
      switch (block.type) {
        case "text":
          out.push({ type: "text", role, text: block.text });
          break;
        case "tool_use":
          out.push({
            type: "tool_use",
            role: "assistant",
            call: {
              id: block.id,
              name: block.name,
              input: block.input as Record<string, unknown> | undefined,
              inputJson: JSON.stringify(block.input ?? {}),
              result: results.get(block.id),
            },
          });
          break;
        default:
          // tool_result blocks are shown on the call they answer, and the
          // remaining variants are not produced by this prototype.
          break;
      }
    }
  }

  for (const block of streaming ?? []) {
    if (!block) continue;
    if (block.type === "text") {
      if (block.text.length > 0) {
        out.push({ type: "text", role: "assistant", text: block.text });
      }
    } else {
      out.push({
        type: "tool_use",
        role: "assistant",
        call: {
          id: block.id,
          name: block.name,
          input: block.input,
          inputJson: block.inputJson,
          result: undefined,
        },
      });
    }
  }
  return out;
}

function toolResult(block: Anthropic.ToolResultBlockParam): ToolResult {
  const content = block.content;
  const text =
    typeof content === "string"
      ? content
      : (content ?? [])
          .map((part) => (part.type === "text" ? part.text : ""))
          .join("");
  return block.is_error
    ? { status: "error", error: text }
    : { status: "ok", text };
}

function parseInput(json: string): Record<string, unknown> | undefined {
  if (json.trim() === "") return {};
  try {
    const parsed = JSON.parse(json) as unknown;
    return typeof parsed === "object" && parsed !== null
      ? (parsed as Record<string, unknown>)
      : undefined;
  } catch {
    return undefined;
  }
}

/** Thinking blocks are not requested by this prototype, so they are warned
 * about rather than silently dropped - when we add them, this is where they
 * surface. */
function startBlock(block: Anthropic.ContentBlock): PendingBlock | undefined {
  switch (block.type) {
    case "text":
      return { type: "text", text: block.text };
    case "tool_use":
      return {
        type: "tool_use",
        id: block.id,
        name: block.name,
        inputJson: "",
        input: undefined,
      };
    default:
      console.warn("unhandled content block", block);
      return undefined;
  }
}

function appendDelta(
  block: PendingBlock | undefined,
  delta: Anthropic.RawContentBlockDelta,
): void {
  switch (delta.type) {
    case "text_delta":
      if (block?.type === "text") block.text += delta.text;
      break;
    case "input_json_delta":
      if (block?.type === "tool_use") block.inputJson += delta.partial_json;
      break;
    default:
      console.warn("unhandled content block delta", delta);
  }
}

