export type ThreadSnapshot = {
  id: ThreadId;
  origin: Origin | null;
  system: string;
  /** String seeds only. A graph-update thread's seed is content blocks, and
   * those threads are never in the tree. */
  seed: string | undefined;
  /** The committed log, minus the seed turn. */
