  thread: ThreadId;
  index: MessageIdx;
  changes: GraphChange[];
};

export type Snapshot = {
  version: number;
  sample: string;
  threads: ThreadSnapshot[];
  nextThreadId: number;
  root: ThreadId;
  graph: GraphSnapshot;
  updates: UpdateSnapshot[];
